<script setup>
import ParticipationTabs from './ParticipationTabs.vue';
import RegistrationActions from './RegistrationActions.vue';
import ReportActions from './ReportActions.vue';
import PagedRecords from './PagedRecords.vue';
import {computed,ref,watch} from 'vue';
const filtersOpen=ref(false),metadataOpen=ref(false);
watch(()=>s.event?.id,()=>{filtersOpen.value=false;metadataOpen.value=false;});
import RegistrationFilters from './RegistrationFilters.vue';
import TargetsPanel from './TargetsPanel.vue';
import BrandLogo from './BrandLogo.vue';
import ReportStamp from './ReportStamp.vue';
// Desktop composition adapted from MDS DashboardPage/ListPage/FormPage templates.
import {s,canEdit,canAdmin,isSuper,canCreateEvent,title,nav,visibleNav,openAdminSettings,run,navigate,selectEvent,showEventList,roleNames,callLabel,modeLabel,responseLabel,utmContent,dateText,number,reports,saveEvent,loadRows,editRow,openContact,setRole} from './store';
import {currentHeaderMode,sidebarCollapsed} from './mds/theme-state';
import ReportFilters from './ReportFilters.vue';import ChartPanel from './ChartPanel.vue';import KpiCard from './KpiCard.vue';import ImportFields from './ImportFields.vue';import SettingsFields from './SettingsFields.vue';import MemberImport from './MemberImport.vue';
const memberColumns=[{key:'name',label:'Họ và tên'},{key:'email',label:'Email'},{key:'role',label:'Quyền'},{key:'actions',label:'Thao tác'}];
const rowColumns=computed(()=>[{key:'name',label:'Họ và tên'},{key:'phone',label:'Số điện thoại'},...(s.rowHasTaxId?[{key:'tax_id',label:'Mã số thuế'}]:[]),{key:'company',label:'Công ty'},{key:'position',label:'Chức vụ'},{key:'submitted_at',label:'Thời gian submit'},{key:'utm_content',label:'utm_content'},{key:'call_status',label:'Gọi xác nhận'},{key:'registration_status',label:'Tình trạng'},{key:'contact_response',label:'Phản hồi'},...(s.event?.mode==='hybrid'?[{key:'attendance_mode',label:'Tham dự'}]:[]),{key:'department',label:'Phòng / nhóm'},{key:'assignee_name',label:'Người phụ trách'},{key:'actions',label:'Thao tác',width:220}].map(c=>({...c,width:c.width||150})));
</script><template><div class="relative flex h-full flex-col overflow-hidden">
<MHeaderBar class="shrink-0" app-name="Event Report" :variant="currentHeaderMode" :user="s.user" :show-assistant="false" :show-chat="false" :show-notifications="false" :show-help="false" :show-more="false" :show-whats-new="false" @settings="s.appearance=true" @user-click="s.dialog='account'" @app-switcher="run(()=>showEventList())" @logo-click="run(()=>showEventList())"><template #logo><BrandLogo/></template><template #search><div class="event-header-picker" :class="{brand:currentHeaderMode==='brand'}"><MCombobox :model-value="s.event?.id" :options="s.events.map(e=>({value:e.id,label:e.name}))" placeholder="Chọn sự kiện" aria-label="Chọn sự kiện" @update:model-value="run(()=>selectEvent($event))"/></div></template></MHeaderBar>
<div class="flex min-h-0 flex-1"><MSidebar :items="[...visibleNav,...(isSuper?[{key:'admins',label:'Thiết lập thành viên',icon:'users'}]:[])]" :model-value="s.route" v-model:collapsed="sidebarCollapsed" @update:model-value="run(()=>$event==='admins'?openAdminSettings():navigate($event))"/><div class="flex min-w-0 min-h-0 flex-1 flex-col">
<div class="toolbar page-toolbar px-4 py-3 shrink-0"><h1>{{title}}</h1><div class="row page-actions"><ReportActions v-if="s.route==='tong-quan'&&s.event" v-model:filters-open="filtersOpen" v-model:metadata-open="metadataOpen"/><MButton v-if="canCreateEvent" variant="secondary" @click="s.dialog='new-event'">Tạo sự kiện</MButton><RegistrationActions v-if="s.route==='du-lieu'&&s.event"/><template v-if="s.route==='tong-quan'&&s.event"><MButton variant="primary" v-if="canEdit" @click="run(()=>navigate('nguon-du-lieu'))">Nhập dữ liệu</MButton></template></div></div>
<main class="scroll-region page-body stack"><div v-if="s.error" role="alert" class="error">{{s.error}}</div><div v-if="s.message" role="status" class="notice">{{s.message}}</div><progress v-if="s.busy" aria-label="Đang xử lý"/><MEmptyState v-if="!s.event" type="initial" title="Chọn hoặc tạo sự kiện để bắt đầu"/>
<template v-else-if="s.route==='tong-quan'"><ParticipationTabs/><ReportFilters :open="filtersOpen"/><div class="toolbar report-navigation"><MTabs :model-value="s.reportTab" :tabs="[{key:'chart',label:'Dashboard'},{key:'table',label:'Bảng số liệu'},{key:'targets',label:'Chi tiết mục tiêu'}]" @update:model-value="s.reportTab=$event;s.table=$event==='table'"/><div v-if="s.reportTab!=='targets'" class="row report-selection"><MCheckbox v-for="r in reports" :key="r.value" v-model="s.selected" :label="r.label" :value="r.value"/></div></div><div v-if="s.reportBusy" role="status" class="card row"><MSpinner/>Đang cập nhật số liệu theo bộ lọc…</div>
<div v-else-if="s.report" data-report class="stack"><ReportStamp :open="metadataOpen"/><div v-if="!s.report.snapshot.id" class="notice">Chưa có dữ liệu để tổng hợp. Chọn Nhập dữ liệu để bắt đầu.</div><div v-else-if="!s.report.current.total" class="notice">Không có đăng ký phù hợp bộ lọc. Chọn “Xem toàn bộ mới nhất” để trở về tổng hợp.</div><p v-if="s.report.current.invited" class="muted">{{number(s.report.current.invited)}} khách đã mời chưa đăng ký; chưa cộng vào KPI.</p><TargetsPanel v-if="s.reportTab==='targets'" /><template v-else><div class="kpi-grid desktop-kpis"><KpiCard v-for="kind in ['total','completion','clevel','ratio','call_rate',...(s.event.mode==='hybrid'&&s.filters.mode==='all'?['online','offline']:[])]" :key="kind" :kind="kind"/></div><p v-if="s.event.mode==='hybrid'&&s.report.current.modes.find(m=>m.value==='unknown')?.count" class="notice">{{number(s.report.current.modes.find(m=>m.value==='unknown').count)}} đăng ký chưa có hình thức tham dự, chưa tính vào Online hoặc Offline.</p><p v-if="s.event.mode==='hybrid'&&s.report.current.modes.find(m=>m.value==='both')?.count" class="muted">Khách chọn cả hai được tính vào Online và Offline; tổng hai ô có thể lớn hơn tổng đăng ký.</p>
<div class="composition-charts"><ChartPanel v-if="s.selected.includes('positions')" title="Cơ cấu chức vụ" :rows="s.report.current.positions" :table="s.table" pie/><ChartPanel v-if="s.selected.includes('sizes')" title="Quy mô doanh nghiệp" :rows="s.report.current.sizes" :table="s.table"/></div><div class="composition-charts compact-charts"><ChartPanel v-if="s.selected.includes('trend')" compact trend title="Xu hướng đăng ký" :rows="s.report.current.trend.map(r=>({...r,label:dateText(r.label),percent:s.report.current.total?r.count/s.report.current.total*100:0}))" :table="s.table"/>
<ChartPanel v-if="s.selected.includes('sources')" compact source title="Nguồn khách" :rows="s.report.current.sourceBreakdowns.find(d=>d.name===s.dimension)?.values||[]" :table="s.table"><template #controls><MCombobox v-model="s.dimension" :options="s.report.sourceDimensions.map(d=>({value:d.name,label:d.name}))" aria-label="Chiều nguồn khách"/></template></ChartPanel></div>
</template></div></template>
<template v-else-if="s.route==='thanh-vien'"><MemberImport/><PagedRecords :key="s.event.id" :rows="s.members" v-slot="{rows:pageRows}"><div class="card"><MDataTable :rows="pageRows" :pagination="false" :columns="memberColumns"><template #cell-role="{row}"><span>{{roleNames[row.role]}}</span></template><template #cell-actions="{row}"><MButton v-if="isSuper||(canAdmin&&row.role==='editor')" variant="link" @click="s.editMember=row;s.dialog='remove-member'">Thu hồi quyền</MButton></template></MDataTable></div></PagedRecords></template>
<template v-else-if="s.route==='du-lieu'"><ParticipationTabs registrations/><RegistrationFilters/><div class="card registration-table"><MDataTable :columns="rowColumns" :rows="s.rows" :page="s.page" :loading="s.rowsBusy" :page-size="s.pageSize" :page-size-options="[20,50,100]" @update:page-size="s.pageSize=$event" :total="s.rowTotal" :has-next="s.page*s.pageSize<s.rowTotal" @update:page="s.page=$event;run(loadRows)"><template #cell-submitted_at="{row}">{{dateText(row.submitted_at)}}</template><template #cell-utm_content="{row}">{{utmContent(row)||'—'}}</template><template #cell-call_status="{row}">{{callLabel(row.call_status)}}</template><template #cell-attendance_mode="{row}">{{modeLabel(row.attendance_mode)}}</template><template #cell-contact_response="{row}">{{responseLabel(row.contact_response)}}</template><template #cell-registration_status="{row}">{{row.registration_status==='invited'?'Đã mời':'Đã đăng ký'}}</template><template #cell-actions="{row}"><div class="row row-edit-actions"><MButton v-if="row.can_edit" variant="link" @click="editRow(row)">Sửa thông tin</MButton><MButton v-if="row.can_edit" variant="link" @click="run(()=>openContact(row))">Liên hệ</MButton></div></template></MDataTable></div></template>
<ImportFields v-else-if="s.route==='nguon-du-lieu'"/><SettingsFields v-else-if="s.route==='muc-tieu'"/></main>
<footer v-if="s.route==='muc-tieu'&&canEdit" class="sticky-actions"><MButton variant="secondary" @click="run(()=>selectEvent(s.event.id))">Hủy thay đổi</MButton><MButton variant="primary" :loading="s.busy" @click="run(saveEvent)">Lưu thiết lập</MButton></footer></div></div></div></template>
